    authored.set("The function is z=x² sin(3x+y³). Find zₓ and zᵧ at (π/3,0).", [{"en": "The function is z=x² sin(3x+y³). Find zₓ and zᵧ at (π/3,0).", "ur": "تفاعل z=x² sin(3x+y³) ہے۔ (π/3,0) پر zₓ اور zᵧ معلوم کریں۔", "ps": "تابع z=x² sin(3x+y³) ده. په (π/3,0) کې zₓ او zᵧ ومومئ."}]);
